package ec.edu.monster.autenticacion; import ec.edu.monster.dto.Peticiones; import ec.edu.monster.modelo.Resultado; import ec.edu.monster.servicio.BancoService; import jakarta.ws.rs.*; import jakarta.ws.rs.core.MediaType; @Path("login") @Produces(MediaType.APPLICATION_JSON) @Consumes(MediaType.APPLICATION_JSON) public class LoginResource {private final BancoService s=new BancoService();@POST public Resultado login(Peticiones.Login p){return p!=null&&s.login(p.getUsuario(),p.getClave())?Resultado.ok("Sesión iniciada.",0):Resultado.error("Usuario o clave inválidos.");}@GET @Path("cliente/{usuario}") @Produces(MediaType.TEXT_PLAIN) public String cliente(@PathParam("usuario")String u){return s.clienteDe(u);}}
